-- Add 24 original higher-context sentence cards alongside the 10,000 licensed cards.
-- Preserve existing IDs, licenses and personal spaced-repetition history.
INSERT OR IGNORE INTO language_cards (id, language, category, term, reading, meaning_zh, explanation, example, example_meaning_zh, example_source_url, source_type, content_type, source_url, highlight_json, vocabulary_expansion_json, grammar_expansion_json) VALUES
  ('ja-sentence-advanced-001', 'ja', '职场语言', '原因は特定できたものの、修正にはもう少し時間がかかる見込みです。', '', '虽然已经找到原因，但预计修复还需要一些时间。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":8,"end":11,"type":"grammar","term":"ものの","meaning":"虽然……但是……","explanation":"承认前项成立，引出不符合预期的后项。"},{"start":26,"end":29,"type":"vocabulary","term":"見込み","meaning":"预计、可能性","explanation":"常用于进度与结果的预期。"}]', '[{"term":"見込み","meaning":"预计、可能性","explanation":"常用于进度与结果的预期。"}]', '[{"term":"ものの","meaning":"虽然……但是……","explanation":"承认前项成立，引出不符合预期的后项。"}]'),
  ('ja-sentence-advanced-002', 'ja', '职场语言', '仕様が確定し次第、影響範囲を確認して担当者に共有します。', '', '规格一确定，我就会确认影响范围并告知相关负责人。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":6,"end":8,"type":"grammar","term":"次第","meaning":"一……就……","explanation":"动词ます形去ます＋次第，表示前一事情完成后立即行动。"},{"start":9,"end":13,"type":"vocabulary","term":"影響範囲","meaning":"影响范围","explanation":"系统变更时用于讨论受影响的部分。"}]', '[{"term":"影響範囲","meaning":"影响范围","explanation":"系统变更时用于讨论受影响的部分。"}]', '[{"term":"次第","meaning":"一……就……","explanation":"动词ます形去ます＋次第，表示前一事情完成后立即行动。"}]'),
  ('ja-sentence-advanced-003', 'ja', '职场语言', '不具合が再現しないため、発生時の操作手順を教えていただけますか。', '', '由于无法复现故障，能请您告诉我故障发生时的操作步骤吗？', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":16,"end":20,"type":"vocabulary","term":"操作手順","meaning":"操作步骤","explanation":"排查故障时要求复现步骤。"},{"start":23,"end":31,"type":"grammar","term":"ていただけますか","meaning":"能否请您……","explanation":"て形＋いただけますか，以较礼貌的方式请求协助。"}]', '[{"term":"操作手順","meaning":"操作步骤","explanation":"排查故障时要求复现步骤。"}]', '[{"term":"ていただけますか","meaning":"能否请您……","explanation":"て形＋いただけますか，以较礼貌的方式请求协助。"}]'),
  ('ja-sentence-advanced-004', 'ja', '职场语言', 'すべてが解決したわけではないので、引き続き様子を見る必要があります。', '', '并不是所有问题都解决了，所以仍有必要继续观察。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":8,"end":14,"type":"grammar","term":"わけではない","meaning":"并非……","explanation":"表达部分否定，不等于全部否定。"},{"start":17,"end":21,"type":"vocabulary","term":"引き続き","meaning":"继续、接下来仍然","explanation":"常用于持续跟进。"}]', '[{"term":"引き続き","meaning":"继续、接下来仍然","explanation":"常用于持续跟进。"}]', '[{"term":"わけではない","meaning":"并非……","explanation":"表达部分否定，不等于全部否定。"}]'),
  ('ja-sentence-advanced-005', 'ja', '职场语言', '急ぎの案件であっても、検証を省略するべきではありません。', '', '即使是紧急项目，也不应该省略验证。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":5,"end":10,"type":"grammar","term":"であっても","meaning":"即使……也……","explanation":"强调前项条件成立，后项原则仍然成立。"},{"start":11,"end":13,"type":"vocabulary","term":"検証","meaning":"验证","explanation":"通过试验或证据确认有效性。"}]', '[{"term":"検証","meaning":"验证","explanation":"通过试验或证据确认有效性。"}]', '[{"term":"であっても","meaning":"即使……也……","explanation":"强调前项条件成立，后项原则仍然成立。"}]'),
  ('ja-sentence-advanced-006', 'ja', '职场语言', '念のためログを確認したところ、同じエラーが複数回発生していました。', '', '为保险起见查看日志后，发现相同的错误发生了多次。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":4,"type":"vocabulary","term":"念のため","meaning":"以防万一","explanation":"说明额外确认的目的。"},{"start":10,"end":14,"type":"grammar","term":"たところ","meaning":"做了……之后发现……","explanation":"描述采取某种行动后得到的结果。"}]', '[{"term":"念のため","meaning":"以防万一","explanation":"说明额外确认的目的。"}]', '[{"term":"たところ","meaning":"做了……之后发现……","explanation":"描述采取某种行动后得到的结果。"}]'),
  ('ja-sentence-advanced-007', 'ja', '职场语言', '変更内容によっては、利用者への事前案内が必要になるかもしれません。', '', '根据变更内容的不同，可能需要提前通知用户。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":4,"end":9,"type":"grammar","term":"によっては","meaning":"根据……的不同，有时会……","explanation":"条件不同可能导致不同结果。"},{"start":15,"end":19,"type":"vocabulary","term":"事前案内","meaning":"事前通知","explanation":"维护与发布时常用。"}]', '[{"term":"事前案内","meaning":"事前通知","explanation":"维护与发布时常用。"}]', '[{"term":"によっては","meaning":"根据……的不同，有时会……","explanation":"条件不同可能导致不同结果。"}]'),
  ('ja-sentence-advanced-008', 'ja', '职场语言', '相手の意図を確認せずに回答すると、かえって誤解を招くおそれがあります。', '', '如果不确认对方的意图就回答，反而可能引起误解。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":9,"end":11,"type":"grammar","term":"ずに","meaning":"不……就……","explanation":"动词ない形去ない＋ずに，表示不做某事而做另一事。"},{"start":21,"end":26,"type":"vocabulary","term":"誤解を招く","meaning":"引发误解","explanation":"侧重给对方造成错误理解。"}]', '[{"term":"誤解を招く","meaning":"引发误解","explanation":"侧重给对方造成错误理解。"}]', '[{"term":"ずに","meaning":"不……就……","explanation":"动词ない形去ない＋ずに，表示不做某事而做另一事。"}]'),
  ('ja-sentence-advanced-009', 'ja', '职场语言', '手戻りを防ぐには、作業を始める前に認識を合わせておくことが重要です。', '', '为了避免返工，在开始工作前统一认识很重要。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":6,"end":8,"type":"grammar","term":"には","meaning":"为了……，需要……","explanation":"此处表示实现目的所需要的条件。"},{"start":17,"end":26,"type":"vocabulary","term":"認識を合わせておく","meaning":"事先统一认识","explanation":"项目开始前对齐目标和范围。"}]', '[{"term":"認識を合わせておく","meaning":"事先统一认识","explanation":"项目开始前对齐目标和范围。"}]', '[{"term":"には","meaning":"为了……，需要……","explanation":"此处表示实现目的所需要的条件。"}]'),
  ('ja-sentence-advanced-010', 'ja', '日常句子', '今日は定時で帰れると思っていたのに、緊急対応が入ってしまいました。', '', '本以为今天能准时下班，结果临时来了紧急任务。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":15,"end":17,"type":"grammar","term":"のに","meaning":"明明……却……","explanation":"表达与预期相反的结果，常带有遗憾语气。"},{"start":18,"end":22,"type":"vocabulary","term":"緊急対応","meaning":"紧急处理","explanation":"突发需要立即处理的事务。"}]', '[{"term":"緊急対応","meaning":"紧急处理","explanation":"突发需要立即处理的事务。"}]', '[{"term":"のに","meaning":"明明……却……","explanation":"表达与预期相反的结果，常带有遗憾语气。"}]'),
  ('ja-sentence-advanced-011', 'ja', '日常句子', '十分に検討したうえで決めたことなので、しばらくは方針を変えないつもりです。', '', '这是充分研究后作出的决定，所以暂时不打算改变方针。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":7,"end":10,"type":"grammar","term":"うえで","meaning":"在……之后再……","explanation":"这里先完成充分研究，再作出决定。"},{"start":24,"end":26,"type":"vocabulary","term":"方針","meaning":"方针、总体方向","explanation":"偏向行动原则或决策方向。"}]', '[{"term":"方針","meaning":"方针、总体方向","explanation":"偏向行动原则或决策方向。"}]', '[{"term":"うえで","meaning":"在……之后再……","explanation":"这里先完成充分研究，再作出决定。"}]'),
  ('ja-sentence-advanced-012', 'ja', '职场语言', '資料を読み込んでおけば、会議中に慌てずに済んだかもしれません。', '', '如果提前仔细读过资料，开会时或许就不用慌张了。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":2,"type":"vocabulary","term":"資料","meaning":"资料、文件","explanation":"常见工作文档。"},{"start":7,"end":11,"type":"grammar","term":"でおけば","meaning":"如果事先……","explanation":"「て／でおく」的假定形，谈论未完成的事前准备及其可能结果。"}]', '[{"term":"資料","meaning":"资料、文件","explanation":"常见工作文档。"}]', '[{"term":"でおけば","meaning":"如果事先……","explanation":"「て／でおく」的假定形，谈论未完成的事前准备及其可能结果。"}]'),
  ('en-sentence-advanced-001', 'en', '职场语言', 'Although we identified the root cause, we still need additional time to verify the fix.', '', '虽然我们找到了根本原因，但仍需要更多时间验证修复结果。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":8,"type":"grammar","term":"Although","meaning":"虽然……但是……","explanation":"引导让步从句，主句与前项形成对照。"},{"start":27,"end":37,"type":"vocabulary","term":"root cause","meaning":"根本原因","explanation":"区分根因与表面症状。"}]', '[{"term":"root cause","meaning":"根本原因","explanation":"区分根因与表面症状。"}]', '[{"term":"Although","meaning":"虽然……但是……","explanation":"引导让步从句，主句与前项形成对照。"}]'),
  ('en-sentence-advanced-002', 'en', '职场语言', 'Before we deploy the update, we should confirm that the existing features still work as expected.', '', '部署更新之前，我们应该确认已有功能仍按预期运行。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":6,"type":"grammar","term":"Before","meaning":"在……之前","explanation":"引导时间从句，指出必须先完成的检查。"},{"start":10,"end":16,"type":"vocabulary","term":"deploy","meaning":"部署、发布","explanation":"将程序发布到运行环境。"}]', '[{"term":"deploy","meaning":"部署、发布","explanation":"将程序发布到运行环境。"}]', '[{"term":"Before","meaning":"在……之前","explanation":"引导时间从句，指出必须先完成的检查。"}]'),
  ('en-sentence-advanced-003', 'en', '职场语言', 'If the requirements change again, we may need to reconsider the release schedule.', '', '如果需求再次变更，我们可能需要重新考虑发布日期。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":2,"type":"grammar","term":"If","meaning":"如果……","explanation":"引导真实条件句；may need to 表示可能需要行动。"},{"start":49,"end":59,"type":"vocabulary","term":"reconsider","meaning":"重新考虑","explanation":"对已有决定再次评估。"}]', '[{"term":"reconsider","meaning":"重新考虑","explanation":"对已有决定再次评估。"}]', '[{"term":"If","meaning":"如果……","explanation":"引导真实条件句；may need to 表示可能需要行动。"}]'),
  ('en-sentence-advanced-004', 'en', '职场语言', 'Could you let me know whether the proposed solution would affect any other teams?', '', '能否告诉我，所提出的解决方案是否会影响其他团队？', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":22,"end":29,"type":"grammar","term":"whether","meaning":"是否","explanation":"引导间接疑问，适合礼貌确认两种可能。"},{"start":34,"end":51,"type":"vocabulary","term":"proposed solution","meaning":"提出的解决方案","explanation":"尚待评估的解决方案。"}]', '[{"term":"proposed solution","meaning":"提出的解决方案","explanation":"尚待评估的解决方案。"}]', '[{"term":"whether","meaning":"是否","explanation":"引导间接疑问，适合礼貌确认两种可能。"}]'),
  ('en-sentence-advanced-005', 'en', '职场语言', 'I had planned to finish the report today, but an urgent issue required my attention.', '', '我原计划今天完成报告，但有紧急问题需要处理。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":42,"end":45,"type":"grammar","term":"but","meaning":"但是","explanation":"前后分句构成计划与实际情况的对比。"},{"start":49,"end":61,"type":"vocabulary","term":"urgent issue","meaning":"紧急问题","explanation":"需要优先处理的事务。"}]', '[{"term":"urgent issue","meaning":"紧急问题","explanation":"需要优先处理的事务。"}]', '[{"term":"but","meaning":"但是","explanation":"前后分句构成计划与实际情况的对比。"}]'),
  ('en-sentence-advanced-006', 'en', '职场语言', 'Once the testing is complete, I will share the results with everyone involved.', '', '测试一完成，我就会向相关人员共享结果。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":4,"type":"grammar","term":"Once","meaning":"一……就……","explanation":"引导时间条件从句，用现在时表示将来的条件。"},{"start":69,"end":77,"type":"vocabulary","term":"involved","meaning":"相关的、参与的","explanation":"everyone involved 指相关人员。"}]', '[{"term":"involved","meaning":"相关的、参与的","explanation":"everyone involved 指相关人员。"}]', '[{"term":"Once","meaning":"一……就……","explanation":"引导时间条件从句，用现在时表示将来的条件。"}]'),
  ('en-sentence-advanced-007', 'en', '职场语言', 'Even though the feature appears to work, we should test it under different conditions.', '', '即使该功能看起来正常，我们仍应在不同条件下测试。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":11,"type":"grammar","term":"Even though","meaning":"即使、尽管","explanation":"强调已观察到的情况不妨碍后项要求。"},{"start":75,"end":85,"type":"vocabulary","term":"conditions","meaning":"条件、环境","explanation":"测试场景的不同条件。"}]', '[{"term":"conditions","meaning":"条件、环境","explanation":"测试场景的不同条件。"}]', '[{"term":"Even though","meaning":"即使、尽管","explanation":"强调已观察到的情况不妨碍后项要求。"}]'),
  ('en-sentence-advanced-008', 'en', '职场语言', 'To avoid misunderstandings, let''s summarize the decision and confirm the next steps in writing.', '', '为了避免误解，我们来总结决定并用文字确认后续步骤。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":8,"type":"grammar","term":"To avoid","meaning":"为了避免……","explanation":"句首不定式表示目的。"},{"start":84,"end":94,"type":"vocabulary","term":"in writing","meaning":"以书面形式","explanation":"以邮件或文档留下记录。"}]', '[{"term":"in writing","meaning":"以书面形式","explanation":"以邮件或文档留下记录。"}]', '[{"term":"To avoid","meaning":"为了避免……","explanation":"句首不定式表示目的。"}]'),
  ('en-sentence-advanced-009', 'en', '职场语言', 'The meeting was postponed because several participants needed more time to prepare.', '', '会议推迟了，因为有几位参与者需要更多准备时间。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":16,"end":25,"type":"vocabulary","term":"postponed","meaning":"被推迟","explanation":"把已计划事项改到更晚时间。"},{"start":26,"end":33,"type":"grammar","term":"because","meaning":"因为……","explanation":"引导原因从句，解释会议延期的理由。"}]', '[{"term":"postponed","meaning":"被推迟","explanation":"把已计划事项改到更晚时间。"}]', '[{"term":"because","meaning":"因为……","explanation":"引导原因从句，解释会议延期的理由。"}]'),
  ('en-sentence-advanced-010', 'en', '职场语言', 'I would appreciate it if you could review the document before tomorrow''s discussion.', '', '如果您能在明天讨论前审阅文档，我会非常感谢。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":8,"end":18,"type":"vocabulary","term":"appreciate","meaning":"感激","explanation":"此处表示感谢对方帮助。"},{"start":22,"end":24,"type":"grammar","term":"if","meaning":"如果……","explanation":"I would appreciate it if... 是礼貌正式的请求。"}]', '[{"term":"appreciate","meaning":"感激","explanation":"此处表示感谢对方帮助。"}]', '[{"term":"if","meaning":"如果……","explanation":"I would appreciate it if... 是礼貌正式的请求。"}]'),
  ('en-sentence-advanced-011', 'en', '职场语言', 'Unless we receive the final approval, we should avoid making changes to production.', '', '除非我们取得最终批准，否则应该避免修改生产环境。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":6,"type":"grammar","term":"Unless","meaning":"除非……否则……","explanation":"Unless 相当于 if not，表示例外条件。"},{"start":22,"end":36,"type":"vocabulary","term":"final approval","meaning":"最终批准","explanation":"组织流程中的正式授权。"}]', '[{"term":"final approval","meaning":"最终批准","explanation":"组织流程中的正式授权。"}]', '[{"term":"Unless","meaning":"除非……否则……","explanation":"Unless 相当于 if not，表示例外条件。"}]'),
  ('en-sentence-advanced-012', 'en', '职场语言', 'By the time the team noticed the problem, several customers had already reported it.', '', '团队发现问题时，已经有几位客户报告了该问题。', '进阶语境练习：理解复句之间的逻辑关系，并注意礼貌程度及实际使用场景。', '', '', '', 'generated', 'sentence', '', '[{"start":0,"end":11,"type":"grammar","term":"By the time","meaning":"到……的时候","explanation":"过去完成时 had reported 表示客户反馈早于团队发现。"},{"start":72,"end":80,"type":"vocabulary","term":"reported","meaning":"已报告","explanation":"这里指反映故障。"}]', '[{"term":"reported","meaning":"已报告","explanation":"这里指反映故障。"}]', '[{"term":"By the time","meaning":"到……的时候","explanation":"过去完成时 had reported 表示客户反馈早于团队发现。"}]');
